// createRun(config) registers a server-owned timed course once, inside start().
// Its areas are existing Trigger Areas; checkpoint positions are safe feet positions.
// Clients read runOf(id, player) and call restartRun(id). Health & Respawn handles moves.
import { game, type Player } from './game'
import { setRespawnPoint, respawnPlayer } from './respawn'
import { advanceRun, freshRun, readRun, type RunAction, type RunState } from './pure/runState'
import { runBoard, runBoardKey } from './pure/runBoard'
import type { Vec3 } from './pure/worldTransform'

export interface RunConfig {
  id: string
  startArea: string
  finishArea: string
  startPosition: Vec3
  checkpoints: Array<{ area: string; position: Vec3 }>
  collectibles: string[]
}

const owners = new Set<string>()
const key = (id: string) => `run:${id}`
const restart = (id: string) => `${key(id)}:restart`

function roster(id: string): Record<string, unknown> {
  const value = game.state[key(id)]
  return typeof value === 'object' && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : {}
}

export function runOf(id: string, player: Player): RunState | null {
  return readRun(roster(id)[player])
}

export function restartRun(id: string, attempt: number): Promise<unknown> {
  return game.request(restart(id), { attempt })
}

export function createRun(config: RunConfig): void {
  if (!config.id.trim() || owners.has(config.id)) throw new Error(`Run Progress needs a unique courseId: ${config.id}`)
  const areas = [config.startArea, config.finishArea, ...config.checkpoints.map((cp) => cp.area), ...config.collectibles]
  if (areas.some((name) => !name.trim()) || new Set(areas.map((name) => name.trim().toLowerCase())).size !== areas.length) {
    throw new Error('Run Progress areas must have distinct, nonempty names.')
  }
  owners.add(config.id)
  const rules = { checkpoints: config.checkpoints.map((cp) => cp.area), collectibles: config.collectibles }
  const save = (player: Player, state: RunState) => game.setState({ [key(config.id)]: { ...roster(config.id), [player]: state } })
  const apply = (player: Player, action: RunAction) => {
    const current = runOf(config.id, player)
    if (current === null) return { ok: false }
    const result = advanceRun(current, action, game.now(), rules)
    if (result.accepted) {
      save(player, result.state)
      if (action.type === 'start' || action.type === 'restart') setRespawnPoint(player, config.startPosition)
      if (action.type === 'checkpoint') setRespawnPoint(player, config.checkpoints[action.index].position)
      if (action.type === 'finish' && result.state.bestMs !== null) {
        game.playerData(player).set({ [`${key(config.id)}:best`]: result.state.bestMs })
        const boardKey = runBoardKey(config.id)
        const board = runBoard(game.saved.get(boardKey), { player, bestMs: result.state.bestMs })
        game.saved.set(boardKey, board)
        game.setState({ [boardKey]: board })
      }
      if (action.type === 'restart') respawnPlayer(player)
    }
    if (result.message) game.broadcast(`${key(config.id)}:notice`, { text: result.message }, player)
    return { ok: result.accepted, message: result.message }
  }
  game.onReady(() => game.setState({ [key(config.id)]: {}, [runBoardKey(config.id)]: runBoard(game.saved.get(runBoardKey(config.id))) }))
  game.onPlayerJoin((player) => {
    const best = game.playerData(player).get()[`${key(config.id)}:best`]
    save(player, freshRun(typeof best === 'number' && Number.isFinite(best) && best >= 0 ? best : null))
  })
  game.onPlayerLeave((player) => {
    const next = { ...roster(config.id) }
    delete next[player]
    game.setState({ [key(config.id)]: next })
  })
  game.onRoundStart(() => {
    for (const player of Object.keys(roster(config.id))) apply(player, { type: 'restart' })
  })
  game.onRequest(restart(config.id), (data: unknown, player) => {
    const attempt = typeof data === 'object' && data !== null ? (data as Record<string, unknown>).attempt : undefined
    if (attempt !== runOf(config.id, player)?.attempt) return { ok: false, message: 'This run has already restarted.' }
    return apply(player, { type: 'restart' })
  })
  game.onEnterArea(config.startArea, (player) => { apply(player, { type: 'start' }) })
  game.onEnterArea(config.finishArea, (player) => { apply(player, { type: 'finish' }) })
  config.checkpoints.forEach((cp, index) => game.onEnterArea(cp.area, (player) => { apply(player, { type: 'checkpoint', index }) }))
  config.collectibles.forEach((id) => game.onEnterArea(id, (player) => { apply(player, { type: 'collect', id }) }))
}
